nderManage() {\n    const promptSettings = controller.snapshot().promptSettings;\n    const tierNames = ['无甲', '轻甲', '中甲', '重甲', '超重甲'];\n    const catKeys = Object.keys(index_js_2.CATEGORY_LABELS);\n    const storedRecords = state.storage.filter((r) => !r.transient && visibleUnitRecord(r));\n    const migrationWarning = state.unitMigrationWarnings.length\n        ? `<div class=\"sub\" style=\"color:var(--danger);margin:6px 0\">⚠ 旧存档有 ${state.unitMigrationWarnings.length} 条单位数据未能完整迁移；原始条目已保留在迁移备份中。${state.unitMigrationWarnings.slice(0, 3).map((w) => `<div>${esc(w)}</div>`).join('')}</div>`\n        : '';\n    const storageRow = (r) => {\n        const editing = state.editingUnit === r.id;\n        if (editing && state.editingDraft)\n            r = state.editingDraft;\n        const isEditingSome = !!state.editingUnit;\n        const line = `<div class=\"manage-row\">\n        <span class=\"tag ${r.side}\">${r.side === 'ally' ? '我方' : '敌方'}</span>\n        <b>${esc(r.name)}</b><label><input type=\"checkbox\" data-role=\"prompt-unit\" data-id=\"${esc(r.id)}\" ${(0, prompt_settings_js_2.promptSelected)(promptSettings, 'unit', r.id) ? 'checked' : ''}>发送给AI</label>\n        <span class=\"dim\">${(0, index_js_2.scaleLabel)({ scale: r.scale, rulesVersion: r.snapshot?.rulesVersion })}Lv${r.level}${r.scale !== 'mook' || r.snapshot?.rulesVersion === 'v2' ? `·XP${r.xp ?? 0}` : ''}·${archName(r.archetype ?? 'infantry', true)}·攻${r.base.atk}防${r.base.def}速${r.base.spd}·${r.scale === 'hero' ? '生命' : '人数'}${r.hp}/${r.base.hpMax}${r.morale !== undefined ? `·士气${r.morale}/${r.base.moraleMax}` : ''}${r.status && r.status !== 'ready' ? `·${r.status}` : ''}${r.zone ? `·${r.zone}/${r.rank === 'rear' ? '后排' : r.rank === 'reserve' ? '预备队' : '前排'}` : ''}</span>\n        <button data-action=\"storage-edit\" data-id=\"${esc(r.id)}\" ${isEditingSome && !editing ? 'disabled' : ''}>${editing ? '编辑中' : '编辑'}</button>\n        ${r.snapshot?.rulesVersion !== 'v2' ? `<button data-action=\"unit-conversion-preview\" data-id=\"${esc(r.id)}\">预览V2转制</button>` : r.history?.at(-1)?.sourceId === 'mechanism-v2-conversion' ? `<button data-action=\"unit-conversion-undo\" data-id=\"${esc(r.id)}\">撤销刚才转制</button>` : ''}\n        <span class=\"sub\">${r.scale === 'hero' ? '生命' : '人数'}/${r.scale === 'hero' ? '生命上限' : '编制上限'}${(0, index_js_2.woundedLabel)(r) ? ' · ' + esc((0, index_js_2.woundedLabel)(r)) : ''} · 档案版本 ${r.revision ?? 1} · 历史 ${r.history?.length ?? 0} 条${r.retired ? ' · 已解散' : ''}</span>\n        <button data-action=\"storage-into\" data-id=\"${esc(r.id)}\" ${state.roster.some((u) => u.id === r.id) || r.retired || r.hp <= 0 || r.status === 'dying' ? 'disabled' : ''} title=\"加入本场参战队伍\">${state.roster.some((u) => u.id === r.id) ? '已参战' : '→参战队伍'}</button>\n        <button data-action=\"storage-del\" data-id=\"${esc(r.id)}\" class=\"danger\" title=\"删除档案及参战引用，同时删除已装备的主武器、副武器、护甲和盾牌\">直接删除（含已装备）</button>\n      </div>`;\n        if (!editing)\n            return line;\n        if (r.snapshot?.rulesVersion === 'v2' && builderEditDraft)\n            return `${line}<div class=\"manage-edit\">${(0, unit_form_js_1.unitForm)('edit', builderEditDraft, reg, { editing: true, managed: r.equipmentManaged })}<div class=\"row\"><button class=\"primary\" data-action=\"storage-preview\" data-id=\"${esc(r.id)}\">预览修改</button><button data-action=\"manage-cancel-edit\">取消编辑</button></div>${builderPreview?.record?.id === r.id ? (0, unit_form_js_1.buildPreview)(builderPreview.unit, r.snapshot) : ''}</div>`;\n        const skillRows = (r.skills ?? []).map((sk, j) => `<div class=\"row\">\n        ${r.snapshot?.rulesVersion === 'v2' ? `<label><input type=\"checkbox\" data-role=\"s-prepared\" data-j=\"${j}\" ${r.preparedAbilityIds?.includes(sk.blueprintId ?? '') ? 'checked' : ''}>准备</label>` : ''}\n        <select data-role=\"s-cat\" data-j=\"${j}\">${catKeys.map((c) => `<option value=\"${esc(c)}\" ${sk.category === c ? 'selected' : ''}>${index_js_2.CATEGORY_LABELS[c]}</option>`).join('')}</select>\n        <input type=\"text\" data-role=\"s-name\" data-j=\"${j}\" value=\"${esc(sk.name ?? '')}\" placeholder=\"技能名（可省略）\" style=\"width:90px\">\n        <input type=\"number\" data-role=\"s-lv\" data-j=\"${j}\" min=\"1\" max=\"10\" value=\"${sk.level ?? ''}\" placeholder=\"L\" style=\"width:44px\">\n        <span class=\"del\" data-action=\"storage-skill-del\" data-id=\"${esc(r.id)}\" data-j=\"${j}\" style=\"cursor:pointer\">✕</span>\n      </div>`).join('');\n        const skillAdd = `<button data-action=\"storage-skill-add\" data-id=\"${esc(r.id)}\">＋技能</button>`;\n        const traitOpts = (0, index_js_2.traitCatalog)(reg)\n            .flatMap((g) => g.traits.map((t) => t))\n            .map((t) => `<option value=\"${esc(t.id)}\" ${(r.traits ?? []).includes(t.id) ? 'selected' : ''}>${t.name}</option>`)\n            .join('') || '<option value=\"\">（无特质）</option>';\n        return `${line}<div class=\"manage-edit\">\n        <div class=\"row\">\n          <label>名称</label><input type=\"text\" data-role=\"s-name0\" value=\"${esc(r.name)}\">\n          <label>原型</label>\n          <select data-role=\"s-arch\">${['infantry', 'ranged', 'mobile'].map((a) => `<option value=\"${esc(a)}\" ${r.archetype === a ? 'selected' : ''}>${archName(a)}</option>`).join('')}</select>\n          <label>等级</label><input type=\"number\" data-role=\"s-level\" min=\"1\" max=\"10\" value=\"${esc(r.level)}\" style=\"width:52px\">\n          <label>刻度</label>\n          <select data-role=\"s-scale\"><option value=\"hero\" ${r.scale === 'hero' ? 'selected' : ''}>个体</option>${r.scale === 'mook' ? '<option value=\"mook\" selected>编队（旧规则，待转制）</option>' : ''}<option value=\"company\" ${r.scale === 'company' ? 'selected' : ''}>编队</option></select>\n        </div>\n        <div class=\"row\">\n          <label>攻</label><input type=\"number\" data-role=\"s-atk\" value=\"${esc(r.base.atk)}\" style=\"width:52px\">\n          <label>防</label><input type=\"number\" data-role=\"s-def\" value=\"${esc(r.base.def)}\" style=\"width:52px\">\n          <label>速</label><input type=\"number\" data-role=\"s-spd\" value=\"${esc(r.base.spd)}\" style=\"width:52px\">\n          <label>${r.scale === 'hero' ? '当前生命' : '当前人数'}</label><input type=\"number\" data-role=\"s-hp-current\" min=\"0\" value=\"${esc(r.hp)}\" style=\"width:68px\">\n          <label>上限</label><input type=\"number\" data-role=\"s-hp\" min=\"1\" value=\"${esc(r.base.hpMax)}\" style=\"width:68px\">\n          <label>当前士气</label><input type=\"number\" data-role=\"s-morale-current\" min=\"0\" value=\"${r.morale ?? ''}\" placeholder=\"—\" style=\"width:52px\">\n          <label>士气上限</label><input type=\"number\" data-role=\"s-morale\" min=\"1\" value=\"${r.base.moraleMax ?? ''}\" placeholder=\"—\" style=\"width:52px\">\n          <label>状态</label><select data-role=\"s-status\">${[['ready', '可战'], ['fled', '已撤离'], ['routing', '溃逃'], ['dying', '濒死']].map(([v, n]) => `<option value=\"${esc(v)}\" ${r.status === v ? 'selected' : ''}>${n}</option>`).join('')}</select>\n        </div>\n        <div class=\"row\">\n          <label>侧别</label><select data-role=\"s-side\"><option value=\"ally\" ${r.side === 'ally' ? 'selected' : ''}>我方</option><option value=\"enemy\" ${r.side === 'enemy' ? 'selected' : ''}>敌方</option></select>\n          <label>武器名</label><input type=\"text\" data-role=\"s-weapon\" value=\"${esc(r.weaponName ?? '')}\" ${r.equipmentManaged ? 'readonly' : ''} placeholder=\"任意名字\" style=\"width:90px\">\n          <label>武器类</label>\n          <select data-role=\"s-wclass\" ${r.equipmentManaged ? 'disabled' : ''}><option value=\"\">（自动）</option>${Object.keys(index_js_2.WEAPON_CLASSES).map((k) => `<option value=\"${esc(k)}\" ${r.weaponClass === k ? 'selected' : ''}>${k}</option>`).join('')}</select>\n          <label>武Lv</label><input type=\"number\" data-role=\"s-wlv\" min=\"1\" max=\"10\" value=\"${r.weaponLevel ?? ''}\" ${r.equipmentManaged ? 'readonly' : ''} placeholder=\"按等级\" style=\"width:48px\">\n        </div>\n        <div class=\"row\">\n          <label>护甲</label>\n          <select data-role=\"s-armor\" ${r.equipmentManaged ? 'disabled' : ''}>${tierNames.map((t, i) => `<option value=\"${esc(i)}\" ${r.armorTier === i ? 'selected' : ''}>${t}</option>`).join('')}<option value=\"\" ${r.armorTier === undefined ? 'selected' : ''}>（自动）</option></select>\n          <label>甲Lv</label><input type=\"number\" data-role=\"s-alv\" min=\"1\" max=\"10\" value=\"${r.armorLevel ?? ''}\" ${r.equipmentManaged ? 'readonly' : ''} placeholder=\"按等级\" style=\"width:48px\">\n        </div>\n        ${r.equipmentManaged ? '<p class=\"sub\">装备已由实物库存管理；在「配装与库存」更换或改造，可预览变化并保留原物品记录。</p>' : ''}\n        <div class=\"eq dim\">技能（类别·名·等级）：</div>\n        ${r.snapshot?.rulesVersion === 'v2' ? `<label>随队预备份额（最多2）<input type=\"number\" data-role=\"s-reserve\" min=\"0\" max=\"2\" value=\"${r.snapshot.resources.reserve ?? 0}\"></label>` : ''}\n        ${skillRows || '<span class=\"sub\">无技能</span>'}\n        ${skillAdd}\n        <div class=\"eq dim\">特质：</div>\n        <select data-role=\"s-traits\" multiple size=\"3\">${traitOpts}</select>\n        <div class=\"row\"><input type=\"text\" data-role=\"s-note\" value=\"${esc(r.note ?? '')}\" placeholder=\"备注（可选）\" style=\"flex:1;min-width:120px\"></div>\n        <div class=\"row\">\n          <button class=\"primary\" data-action=\"storage-save\" data-id=\"${esc(r.id)}\">保存</button>\n          <button data-action=\"manage-cancel-edit\">取消</button>\n          <span class=\"sub\">改的是储存器档案；点「→编制」才作为上场单位。</span>\n        </div>\n      </div>`;\n    };\n    const storageBlock = storedRecords.length\n        ? `<div class=\"manage-list\">${storedRecords.map((r) => storageRow(r)).join('') || '<span class=\"sub\">储存器为空——战斗中出现且未死的单位会自动存入</span>'}</div>`\n        : '<span class=\"sub\">储存器为空——战斗中出现且未死的单位会自动存入</span>';\n    const rosterRow = (u, i) => {\n        const marks = `${u.id === state.protagonistId ? '★' : ''}${u.side === 'ally' && u.id === state.commanderId ? '⚑' : ''}`;\n        const seq = unitSeq(u);\n        return `<div class=\"manage-row\">\n        <span class=\"tag ${u.side}\">${u.side === 'ally' ? '我方' : '敌方'}</span>\n        <b>${marks}${esc(u.name)}${seq ? ` <span class=\"seq\">#${seq}</span>` : ''}</b>\n        <span class=\"dim\">${(0, index_js_2.scaleLabel)(u)}Lv${u.level}·${u.scale === 'hero' ? '生命' : '人数'}${u.hp}/${u.base.hpMax}</span>\n        ${u.scale === 'company' ? `<label>战区<select data-role=\"deploy-zone\" data-unit=\"${esc(u.id)}\" ${currentBattle() ? 'disabled' : ''}><option value=\"\">自动</option>${['左翼', '中军', '右翼'].map((z) => `<option value=\"${esc(z)}\" ${formationZone(u) === z ? 'selected' : ''}>${z}</option>`).join('')}</select></label><label>阵列<select data-role=\"deploy-rank\" data-unit=\"${esc(u.id)}\" ${currentBattle() ? 'disabled' : ''}>${[['front', '前排'], ['rear', '后排'], ['reserve', '预备队']].map(([v, n]) => `<option value=\"${esc(v)}\" ${(formationRank(u) ?? defaultRank(u)) === v ? 'selected' : ''}>${n}</option>`).join('')}</select></label>` : ''}\n        <button data-action=\"roster-del\" data-i=\"${i}\" class=\"danger\">删除</button>\n      </div>`;\n    };\n    const rosterBlock = state.roster.length\n        ? `<div class=\"manage-list\">${state.roster.filter(visibleUnitRecord).map(rosterRow).join('')}</div>`\n        : '<span class=\"sub\">编制为空——在「① 编制」生成，或从下方储存器点「→编制」加入。</span>';\n    return `<section>\n    <div class=\"row\" style=\"justify-content:space-between\"><h2 style=\"margin:0\">🧭 编制与储存器 <small class=\"sub\">编制=上场单位；储存器=历史存活档案库（可编辑）</small></h2>\n    <button data-action=\"manage-toggle\">${state.manageOpen ? '收起' : '展开'}</button></div>\n    ${migrationWarning}\n    ${state.manageOpen ? `<div>\n      <div style=\"margin-top:6px\"><b style=\"color:var(--dim)\">已知编制（${state.roster.filter(visibleUnitRecord).length}）</b></div>\n      ${rosterBlock}\n      <div style=\"margin-top:12px\"><b style=\"color:var(--dim)\">编制储存器（${storedRecords.length}）</b><div class=\"row\"><button data-action=\"prompt-select-units\" data-selected=\"true\">发送全选</button><button data-action=\"prompt-select-units\" data-selected=\"false\">发送全不选</button><span class=\"sub\">仅控制动态单位清单，不改变参战队伍；新单位默认选中。</span></div>\n        <span class=\"sub\">同一 id 保留装备、战损和经验；阵亡/解散留档，召唤不自动建档。分遣拆分尚不支持。</span></div>\n      ${storageBlock}\n    </div>` : '<span class=\"sub\">点「展开」管理上场编制与储存器档案。</span>'}\n  </section>`;\n}\nfunction renderRole() {\n    const hero = state.roster.find((u) => u.id === state.protagonistId && u.side === 'ally');\n    if (!hero) {\n        return `<section>\n      <h2>👤 角色</h2>\n      <span class=\"sub\">在队伍的单位操作中设定主控后，可查看近况并发送给正文AI。</span>\n    </section>`;\n    }\n    if (hero.rulesVersion === 'v2') {\n        const current = currentBattle()?.combatants.find((u) => u.id === hero.id) ?? hero;\n        const progress = (0, index_js_2.xpProgress)(hero), opened = state.expandedUnits.has('role:' + hero.id);\n        return `<section class=\"role-overview\"><h2>主控近况 <small>${esc(hero.name)}</small></h2><p>${current.scale === 'hero' ? '生命' : '人数'} ${current.hp}/${current.base.hpMax} · 训练${hero.level}${progress ? ' · 本级经验' + (0, index_js_2.xpLabel)(progress.current) + '/' + progress.next : ''} · 累计XP ${(0, index_js_2.xpLabel)(hero.xp ?? 0)}</p><div class=\"row\"><button data-action=\"role-detail\" data-id=\"${esc(hero.id)}\">${opened ? '收起详情' : '装备与状态'}</button><button data-action=\"role-inject\">发送当前近况</button></div>${opened ? '<div class=\"role-details\">' + unitDetailHtml(current, battleFieldTags()) + '</div>' : ''}</section>`;\n    }\n    const prog = (0, index_js_2.xpProgress)(hero);\n    const xpLine = prog\n        ? `本级经验 <b>${(0, index_js_2.xpLabel)(prog.current)}</b>/${prog.next}` + (hero.level < 10 ? `（距 ${(0, index_js_2.xpLabel)(prog.next - prog.current)} 升级）` : '')\n        : `经验 <b>${hero.xp ?? 0}</b>（满级）`;\n    const tierNames = ['无甲', '轻甲', '中甲', '重甲', '超重甲'];\n    const equip = hero.weapon\n        ? `<div class=\"eq\"><b>武器</b>