     <button data-action=\"role-inject\">发送角色状态 → 给AI</button></div>\n    </div>\n  </section>`;\n}\nfunction logDetailHtml(e) {\n    const r = e.resolution;\n    if (!r)\n        return '';\n    if (r.packetCount)\n        return `<b>${esc(r.text)}</b><br><span class=\"dim\">有效参战${r.participants?.toFixed(1)}人 · 各组损失：${r.packetRolls?.map(p => p.damage).join(' / ')}；实际扣除以目标余量为上限</span>`;\n    const lines = [];\n    const head = `<b>${esc(r.attackerName)} → ${esc(r.defenderName)}</b>`;\n    if (!r.hit) {\n        const roll = r.attackRoll ? `d20[${r.attackRoll.kept.join(',')}]` : '';\n        lines.push(`${head}：${roll}${r.netAtk >= 0 ? '+' : ''}${r.netAtk} vs 防御${r.targetDef} —— <b class=\"miss\">未命中</b>`);\n        if (r.atkDetail)\n            lines.push(`<span class=\"dim\">加值栈：${esc(r.atkDetail)}</span>`);\n        return lines.join('<br>');\n    }\n    const rollPart = r.attackRoll\n        ? `d20[${r.attackRoll.kept.join(',')}]${r.crit ? ' 暴击!' : ''}${r.netAtk >= 0 ? '+' : ''}${r.netAtk}=${r.attackRoll.total + r.netAtk} vs 防御${r.targetDef}`\n        : `命中率${Math.round((r.hitChance ?? 0) * 100)}%`;\n    lines.push(`${head}：${rollPart} —— <b class=\"hit\">命中</b>`);\n    lines.push(`<span class=\"dim\">净攻${r.netAtk}｜目标防${r.targetDef}${r.drPercent ? `｜护甲减伤${r.drPercent}%` : ''}${r.dmgMult !== 1 ? `｜攻倍×${r.dmgMult}` : ''}${r.wardMult !== 1 ? `｜守护×${r.wardMult}` : ''}</span>`);\n    if (r.baseRoll)\n        lines.push(`<span class=\"dim\">普通段 ${r.baseRoll.rolls.join('+')}${r.baseRoll.flat ? '+' + r.baseRoll.flat : ''} → 减伤后 ${r.baseAfterDR}</span>`);\n    if (r.apRoll || r.apTotal > 0)\n        lines.push(`<span class=\"dim\">破甲段 ${r.apTotal}</span>`);\n    lines.push(`<b>最终伤害 ${r.finalDamage}</b> → ${esc(r.defenderName)} HP ${r.hpBefore}→${r.hpAfter}`);\n    return lines.join('<br>');\n}\nfunction renderSmall() {\n    const b = state.small;\n    if (!b) {\n        return `<section><h2>② 小规模战斗</h2>\n      <button class=\"primary\" data-action=\"small-start\" ${!roste